import CryptoWalletSaveForm from '@/Components/Forms/Backend/Crypto/CryptoWalletSaveForm';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import { Check, Coins, Copy, Network, QrCode } from 'lucide-react';
import React from 'react';
import z from 'zod';

export function useCryptoWalletAddressConfig(props: CrudPageProps): CrudConfig {
    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const routePrefix = modelProperty?.routePrefix;

    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Crypto wallet addresses'), href: route(`${routePrefix}.index`) },
    ];

    return {
        formComponent: CryptoWalletSaveForm,

        resource: 'crypto-wallet-address',
        resourcePlural: 'crypto-wallet-addresses',

        title: t('Crypto Wallet Addresses'),
        description: t('Manage crypto wallet addresses and QR codes'),

        routes: {
            index: `${routePrefix}.index`,
            create: `${routePrefix}.create`,
            edit: `${routePrefix}.edit`,
            store: `${routePrefix}.store`,
            update: `${routePrefix}.update`,
            destroy: `${routePrefix}.destroy`,
            updateStatus: `${routePrefix}.update.status`,
        },

        form: {
            title: {
                create: t('Add Wallet Address'),
                edit: t('Edit Wallet Address'),
            },
            submitButtonText: {
                create: t('Add Address'),
                edit: t('Update Address'),
            },

            fields: [
                {
                    name: 'crypto_id',
                    label: t('Crypto Currency'),
                    type: 'select',
                    required: true,
                    options: props?.cryptoCurrencyOptions || [],
                    gridColumn: 'span 3',
                },
                {
                    name: 'network',
                    label: t('Network'),
                    type: 'text',
                    required: true,
                    placeholder: 'TRC20 / ERC20 / BEP20',
                    gridColumn: 'span 1',
                },
                {
                    name: 'address',
                    label: t('Wallet Address'),
                    type: 'text',
                    required: true,
                    placeholder: '0x0000000000000000000000000000000000000000',
                    gridColumn: 'span 1',
                },

                {
                    name: 'status',
                    label: t('Status'),
                    type: 'select',
                    required: true,
                    options: [
                        { value: 'active', label: t('Active') },
                        { value: 'inactive', label: t('Inactive') },
                    ],
                },
                {
                    name: 'notes',
                    label: t('Notes'),
                    type: 'textarea',
                    placeholder: t('Notes'),
                    gridColumn: 'span 3',
                },

            ],
        },

        formValidationRules: {
            crypto_id: z.string().min(1, 'Crypto is required'),
            network: z.string().min(1, 'Network is required'),
            address: z.string().min(1, 'Address is required'),
            notes: z.string().optional(),
            status: z.string().min(1, 'Status is required'),
        },

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Crypto Currencies addresses'), href: null, active: true },
            ],
            create: [
                ...baseBreadcrumbs,
                { label: t('Add address'), href: null, active: true },
            ],
            update: [
                ...baseBreadcrumbs,
                { label: t('Edit address'), href: null, active: true },
            ],
        },


        table: {

            selectable: false,
            searchable: true,
            serializable: true,
            searchPlaceholder: t('Search by name or symbol…'),
            sortable: true,
            defaultSort: 'sort_order',
            defaultSortDirection: 'asc',
            emptyMessage: t('No wallet addresses found.'),
            emptyMessageIcon: Network,

            columns: [


                {
                    key: 'name',
                    label: t('Coin'),
                    sortable: false,
                    filterable: true,
                    priority: 0,
                    defaultIcon: Coins,

                    render: (row: any) => (

                        <div className="flex items-center gap-3 max-w-full">
                            {/* Avatar */}
                            <div className="flex-shrink-0 w-10 h-10">
                                {row.crypto?.images?.small ? (
                                    <img
                                        src={row.crypto?.images?.small}
                                        alt={row?.crypto?.name}
                                        className="w-10 h-10 object-cover rounded-full border"
                                    />
                                ) : (
                                    <div className="flex items-center justify-center w-10 h-10 rounded-full border bg-gray-100 dark:bg-gray-700">
                                        <Coins className="w-5 h-5 text-gray-400" />
                                    </div>
                                )}
                            </div>

                            {/* Text */}
                            <div className="flex-1 min-w-0">
                                <p
                                    className="text-sm font-medium text-gray-900 dark:text-gray-100
                          truncate leading-tight"
                                    title={row.crypto?.name}
                                >
                                    {row.crypto?.name}
                                </p>
                            </div>
                        </div>
                    )
                },



                {
                    key: 'network',
                    label: t('Network'),
                    render: (row: any) => (
                        <span className="">{row.network}</span>
                    ),
                },

                {
                    key: 'address',
                    label: 'Address',
                    render: (row: any) => {

                        const [copied, setCopied] = React.useState(false);

                        const copyToClipboard = async () => {
                            try {
                                await navigator.clipboard.writeText(row.address);
                                setCopied(true);
                                setTimeout(() => setCopied(false), 1500);
                            } catch (err) {
                                console.error(err);
                            }
                        };

                        return (
                            <div className="flex items-center justify-between gap-2">

                                {/* wallet text */}
                                <code className="text-xs bg-muted px-2 py-1 rounded">
                                    {row.address}
                                </code>

                                {/* copy button */}
                                <button
                                    onClick={copyToClipboard}
                                    className="p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-700"
                                >
                                    {copied ? (
                                        <Check className="w-4 h-4 text-green-600" />
                                    ) : (
                                        <Copy className="w-4 h-4" />
                                    )}
                                </button>

                            </div>
                        );
                    }
                },
                {
                    key: 'qr_code',
                    label: t('QR'),
                    render: (row: any) =>
                        row.qr_code_url ? (
                            <img
                                src={row.qr_code_url}
                                className="w-10 h-10 border rounded"
                            />
                        ) : (
                            <QrCode className="w-5 h-5 text-muted-foreground" />
                        ),
                },
                {
                    key: 'status',
                    label: t('Status'),
                    render: (row: any) => <StatusBadge status={row.status} />,
                },
            ],
        },

        permissions: {
            actions: {
                index: 'crypto-wallet-address.view',
                create: 'crypto-wallet-address.create',
                edit: 'crypto-wallet-address.edit',
                update: 'crypto-wallet-address.edit',
                delete: 'crypto-wallet-address.delete',
            },

        },

        filters: {
            searchFields: ['address', 'network', 'crypto ame'],
            filterFields: props.advanceFilterOptions,
        },

        labels: {
            singular: 'Cryptocurrency address',
            plural: 'Cryptocurrency addresses',
            key: 'address',
        },

        saveAlertInfo: {
            title: t('Cryptocurrency Address Configuration'),
            description: t('The cryptocurrency address configuration has been updated successfully!'),
        },




    };
}